
CREATE DATABASE customer_analysis;
USE customer_analysis;
SHOW DATABASES;
Select * from customer_data;

-- What is the total revenue generated by male vs female customers ?
select gender , SUM(purchase_amount) as revenue
from customer_data
group by gender;

-- Which customer used a discount bill still spent more than the average purchase amount ?
select customer_id,purchase_amount
from customer_data
where discount_applied='Yes' and purchase_amount>= (select AVG(purchase_amount)from customer_data)


